# ============================================================
# TS DATASET SCIENTIFIC VALIDATOR
# ============================================================
#
# File:
#     src/timeseries/ts_dataset_validation.py
#
# Purpose:
#     Scientifically validate the route-progress TS dataset
#     generated by ts_dataset.py.
#
# Dataset design:
#     ICE telemetry sequence
#             ↓
#     Route-progress representation
#             ↓
#     EV six-phase behaviour
#
# Predictive phases:
#     STOP
#     IDLE
#     INCHING
#     ACC
#     DEC
#     CRUISE
#
# Excluded operational phases:
#     ICE -> REFUELLING
#     EV  -> CHARGING
#
# Important:
#     Total TAT is NOT required to equal only the six
#     predictive phases.
#
#     Total TAT =
#         Six predictive phase time
#         + excluded operational time
#
# ============================================================


