REQUIRED_COLUMNS += EV_DISTANCE_COLUMNS


# ============================================================
# 5. UTILITY FUNCTIONS
# ============================================================

def status(condition):

    return "PASS" if condition else "FAIL"


def safe_float(value):

    try:

        value = float(value)

        if np.isnan(value):
            return 0.0

        if np.isinf(value):
            return 0.0

        return value

    except Exception:

        return 0.0


def percentage_difference(value_a, value_b):

    value_a = safe_float(value_a)
    value_b = safe_float(value_b)

    denominator = max(
        abs(value_a),
        abs(value_b),
        1e-12
    )

    return (
        abs(value_a - value_b)
        / denominator
        * 100.0
    )


# ============================================================
# 6. LOAD DATASET
# ============================================================

def load_dataset():

    print("=" * 70)
    print("TS DATASET SCIENTIFIC VALIDATION")
    print("=" * 70)

    if not DATASET_FILE.exists():

        raise FileNotFoundError(
            f"\nDataset not found:\n{DATASET_FILE}"
        )

    print("\nDataset:")
    print(DATASET_FILE)

    df = pd.read_excel(
        DATASET_FILE,
        sheet_name="Route_Progress_All"
    )

    print(
        f"\nRows loaded    : {len(df)}"
    )

    print(
        f"Columns loaded : {len(df.columns)}"
    )

    return df


# ============================================================
# 7. STRUCTURAL VALIDATION
# ============================================================

def validate_structure(df):

    print("\n" + "=" * 70)
    print("1. STRUCTURAL VALIDATION")
    print("=" * 70)

    missing_columns = [
        column
        for column in REQUIRED_COLUMNS
        if column not in df.columns
    ]

    found_count = (
        len(REQUIRED_COLUMNS)
        - len(missing_columns)
    )

    print(
        f"Expected columns : "
        f"{len(REQUIRED_COLUMNS)}"
    )

    print(
        f"Found columns    : "
        f"{found_count}"
    )

    print(
        f"Missing columns  : "
        f"{len(missing_columns)}"
    )

    if missing_columns:

        print("\nMissing columns:")

        for column in missing_columns:

            print(
                f"   - {column}"
            )

    result = {

        "Check":
            "Required columns",

        "Expected_Columns":
            len(REQUIRED_COLUMNS),

        "Found_Columns":
            found_count,

        "Missing_Columns":
            ", ".join(missing_columns),

        "Status":
            status(
                len(missing_columns) == 0
            ),
    }

    return result


# ============================================================
# 8. MISSING VALUE VALIDATION
# ============================================================

def validate_missing_values(df):

    print("\n" + "=" * 70)
    print("2. MISSING VALUE VALIDATION")
    print("=" * 70)

    total_missing = int(
        df.isna()
        .sum()
        .sum()
    )

    print(
        f"Total missing values : "
        f"{total_missing}"
    )

    missing_columns = (
        df.isna()
        .sum()
    )

    missing_columns = (
        missing_columns[
            missing_columns > 0
        ]
        .sort_values(
            ascending=False
        )
    )

    if len(missing_columns) > 0:

        print(
            "\nColumns containing missing values:"
        )

        for column, count in (
            missing_columns.items()
        ):

            print(
                f"   {column}: {count}"
            )

    result = {

        "Check":
            "Missing values",

        "Missing_Count":
            total_missing,

        "Status":
            status(
                total_missing == 0
            ),
    }

    return result


# ============================================================
# 9. PAIR INTEGRITY
# ============================================================

def validate_pair_integrity(df):

    print("\n" + "=" * 70)
    print("3. PAIR INTEGRITY")
    print("=" * 70)

    pair_counts = (
        df.groupby("Pair_ID")
        .size()
        .sort_index()
    )

    invalid_pairs = (
        pair_counts[
            pair_counts
            != EXPECTED_BINS_PER_PAIR
        ]
    )

    unique_pairs = len(pair_counts)

    print(
        f"Unique pairs : "
        f"{unique_pairs}"
    )

    print(
        f"Expected bins per pair : "
        f"{EXPECTED_BINS_PER_PAIR}"
    )

    print(
        f"Pairs with incorrect row count : "
        f"{len(invalid_pairs)}"
    )

    if len(invalid_pairs) > 0:

        print("\nInvalid pairs:")

        for pair_id, count in (
            invalid_pairs.items()
        ):

            print(
                f"   {pair_id}: "
                f"{count} rows"
            )

    pair_table = pd.DataFrame({

        "Pair_ID":
            pair_counts.index,

        "Rows":
            pair_counts.values,

        "Expected_Rows":
            EXPECTED_BINS_PER_PAIR,

        "Status":
            [
                "PASS"
                if value
                == EXPECTED_BINS_PER_PAIR
                else "FAIL"
                for value
                in pair_counts.values
            ],
    })

    result = {

        "Check":
            "Pair integrity",

        "Unique_Pairs":
            unique_pairs,

        "Expected_Rows_Per_Pair":
            EXPECTED_BINS_PER_PAIR,

        "Invalid_Pairs":
            len(invalid_pairs),

        "Status":
            status(
                len(invalid_pairs) == 0
            ),
    }

    return result, pair_table


# ============================================================
# 10. ROUTE BIN COMPLETENESS
# ============================================================

def validate_route_bins(df):

    print("\n" + "=" * 70)
    print("4. ROUTE BIN VALIDATION")
    print("=" * 70)

    records = []

    expected_bins = set(
        range(
            EXPECTED_BINS_PER_PAIR
        )
    )

    for pair_id, group in (
        df.groupby("Pair_ID")
    ):

        actual_bins = set(
            group[
                "Route_Bin"
            ]
            .astype(int)
            .tolist()
        )

        missing_bins = (
            expected_bins
            - actual_bins
        )

        extra_bins = (
            actual_bins
            - expected_bins
        )

        records.append({

            "Pair_ID":
                pair_id,

            "Missing_Bins":
                len(missing_bins),

            "Extra_Bins":
                len(extra_bins),

            "Status":
                (
                    "PASS"
                    if (
                        len(missing_bins)
                        == 0
                        and
                        len(extra_bins)
                        == 0
                    )
                    else
                    "FAIL"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    failed_pairs = int(
        (
            result_df["Status"]
            == "FAIL"
        ).sum()
    )

    print(
        f"Pairs with missing/extra bins : "
        f"{failed_pairs}"
    )

    result = {

        "Check":
            "Route-bin completeness",

        "Problem_Pairs":
            failed_pairs,

        "Status":
            status(
                failed_pairs == 0
            ),
    }

    return result, result_df


# ============================================================
# 11. ROUTE PROGRESS VALIDATION
# ============================================================

def validate_route_progress(df):

    print("\n" + "=" * 70)
    print("5. ROUTE PROGRESS VALIDATION")
    print("=" * 70)

    records = []

    for pair_id, group in (
        df.groupby("Pair_ID")
    ):

        group = group.sort_values(
            "Route_Bin"
        )

        route_bins = (
            group[
                "Route_Bin"
            ]
            .astype(int)
            .to_numpy()
        )

        route_progress = (
            group[
                "Route_Progress"
            ]
            .astype(float)
            .to_numpy()
        )

        expected_progress = (
            route_bins + 0.5
        ) / EXPECTED_BINS_PER_PAIR

        expected_order = (
            np.diff(route_progress)
            >= 0
        ).all()

        expected_values = np.allclose(
            route_progress,
            expected_progress,
            atol=ROUTE_PROGRESS_TOLERANCE
        )

        records.append({

            "Pair_ID":
                pair_id,

            "Progress_Ordered":
                expected_order,

            "Expected_Progress":
                expected_values,

            "Status":
                (
                    "PASS"
                    if (
                        expected_order
                        and expected_values
                    )
                    else "FAIL"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    failed_pairs = int(
        (
            result_df["Status"]
            == "FAIL"
        ).sum()
    )

    print(
        f"Pairs with route-progress issues : "
        f"{failed_pairs}"
    )

    result = {

        "Check":
            "Route progress ordering",

        "Problem_Pairs":
            failed_pairs,

        "Status":
            status(
                failed_pairs == 0
            ),
    }

    return result, result_df


# ============================================================
# 12. DISTANCE ACCOUNTING
# ============================================================
#
# IMPORTANT:
#
# The six predictive phase distances are:
#
#     STOP
#     IDLE
#     INCHING
#     ACC
#     DEC
#     CRUISE
#
# They do not necessarily represent the complete trip
# distance because operational phases such as refuelling
# or charging are handled separately.
#
# Therefore this validator does NOT require:
#
#     Total Distance
#         ==
#     Six predictive phase distance
#
# Instead it checks:
#
#     1. No negative distances
#     2. Route representation is finite
#     3. Six-phase distance <= total distance
#     4. Remaining distance is physically interpretable
#
# ============================================================

def validate_distance_accounting(df):

    print("\n" + "=" * 70)
    print("6. DISTANCE ACCOUNTING")
    print("=" * 70)

    records = []

    for pair_id, group in (
        df.groupby("Pair_ID")
    ):

        # ----------------------------------------------------
        # ICE
        # ----------------------------------------------------

        ice_total = (
            group[
                "ICE_Distance_Total_km"
            ]
            .sum()
        )

        ice_phase = (
            group[
                ICE_DISTANCE_COLUMNS
            ]
            .sum()
            .sum()
        )

        ice_remaining = (
            ice_total
            - ice_phase
        )

        ice_valid = (

            ice_total >= -1e-9

            and

            ice_phase >= -1e-9

            and

            ice_remaining
            >= -DISTANCE_TOLERANCE_KM
        )

        # ----------------------------------------------------
        # EV
        # ----------------------------------------------------

        ev_phase = (
            group[
                EV_DISTANCE_COLUMNS
            ]
            .sum()
            .sum()
        )

        if "EV_Distance_Total_km" in df.columns:

            ev_total = (
                group[
                    "EV_Distance_Total_km"
                ]
                .sum()
            )

            ev_remaining = (
                ev_total
                - ev_phase
            )

            ev_valid = (

                ev_total >= -1e-9

                and

                ev_phase >= -1e-9

                and

                ev_remaining
                >= -DISTANCE_TOLERANCE_KM
            )

        else:

            ev_total = np.nan
            ev_remaining = np.nan
            ev_valid = True

        records.append({

            "Pair_ID":
                pair_id,

            "ICE_Total_Distance_km":
                ice_total,

            "ICE_Six_Phase_Distance_km":
                ice_phase,

            "ICE_Excluded_or_Unassigned_Distance_km":
                ice_remaining,

            "ICE_Status":
                status(ice_valid),

            "EV_Total_Distance_km":
                ev_total,

            "EV_Six_Phase_Distance_km":
                ev_phase,

            "EV_Excluded_or_Unassigned_Distance_km":
                ev_remaining,

            "EV_Status":
                (
                    status(ev_valid)
                    if
                    "EV_Distance_Total_km"
                    in df.columns
                    else
                    "NOT_AVAILABLE"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    ice_pass = (
        result_df[
            "ICE_Status"
        ]
        == "PASS"
    ).all()

    if "EV_Distance_Total_km" in df.columns:

        ev_pass = (
            result_df[
                "EV_Status"
            ]
            == "PASS"
        ).all()

    else:

        ev_pass = True

    print(
        f"ICE distance accounting : "
        f"{status(ice_pass)}"
    )

    if "EV_Distance_Total_km" in df.columns:

        print(
            f"EV distance accounting  : "
            f"{status(ev_pass)}"
        )

    else:

        print(
            "EV distance accounting  : "
            "NOT_AVAILABLE"
        )

    overall_pass = (
        ice_pass
        and ev_pass
    )

    result = {

        "Check":
            "Distance accounting",

        "ICE_Status":
            status(ice_pass),

        "EV_Status":
            (
                status(ev_pass)
                if
                "EV_Distance_Total_km"
                in df.columns
                else
                "NOT_AVAILABLE"
            ),

        "Status":
            (
                "PASS"
                if overall_pass
                else "FAIL"
            ),
    }

    return result, result_df


# ============================================================
# 13. TIME ACCOUNTING
# ============================================================
#
# Correct scientific accounting:
#
# ICE:
#
# Total ICE TAT
#     =
# Six predictive phase time
#     +
# Refuelling / excluded operational time
#
#
# EV:
#
# Total EV TAT
#     =
# Six predictive phase time
#     +
# Charging / excluded operational time
#
# Therefore six-phase time does NOT have to equal total TAT.
#
# ============================================================

def validate_time_accounting(df):

    print("\n" + "=" * 70)
    print("7. TIME ACCOUNTING")
    print("=" * 70)

    records = []

    for pair_id, group in (
        df.groupby("Pair_ID")
    ):

        # ----------------------------------------------------
        # ICE
        # ----------------------------------------------------

        ice_total = (
            group[
                "ICE_Time_Total_min"
            ]
            .sum()
        )

        ice_phase = (
            group[
                ICE_TIME_COLUMNS
            ]
            .sum()
            .sum()
        )

        ice_excluded = (
            ice_total
            - ice_phase
        )

        ice_reconstructed = (
            ice_phase
            + ice_excluded
        )

        ice_difference = (
            ice_total
            - ice_reconstructed
        )

        ice_valid = (

            ice_total >= -1e-9

            and

            ice_phase >= -1e-9

            and

            ice_excluded
            >= -TIME_TOLERANCE_MIN

            and

            abs(ice_difference)
            <= TIME_TOLERANCE_MIN
        )

        # ----------------------------------------------------
        # EV
        # ----------------------------------------------------

        ev_phase = (
            group[
                EV_TIME_COLUMNS
            ]
            .sum()
            .sum()
        )

        if "EV_Time_Total_min" in df.columns:

            ev_total = (
                group[
                    "EV_Time_Total_min"
                ]
                .sum()
            )

            ev_excluded = (
                ev_total
                - ev_phase
            )

            ev_reconstructed = (
                ev_phase
                + ev_excluded
            )

            ev_difference = (
                ev_total
                - ev_reconstructed
            )

            ev_valid = (

                ev_total >= -1e-9

                and

                ev_phase >= -1e-9

                and

                ev_excluded
                >= -TIME_TOLERANCE_MIN

                and

                abs(ev_difference)
                <= TIME_TOLERANCE_MIN
            )

        else:

            ev_total = np.nan
            ev_excluded = np.nan
            ev_reconstructed = np.nan
            ev_difference = np.nan
            ev_valid = True

        records.append({

            "Pair_ID":
                pair_id,

            "ICE_Total_TAT_min":
                ice_total,

            "ICE_Six_Phase_Time_min":
                ice_phase,

            "ICE_Excluded_Operational_Time_min":
                ice_excluded,

            "ICE_Reconstructed_TAT_min":
                ice_reconstructed,

            "ICE_Difference_min":
                ice_difference,

            "ICE_Status":
                status(ice_valid),

            "EV_Total_TAT_min":
                ev_total,

            "EV_Six_Phase_Time_min":
                ev_phase,

            "EV_Excluded_Operational_Time_min":
                ev_excluded,

            "EV_Reconstructed_TAT_min":
                ev_reconstructed,

            "EV_Difference_min":
                ev_difference,

            "EV_Status":
                (
                    status(ev_valid)
                    if
                    "EV_Time_Total_min"
                    in df.columns
                    else
                    "NOT_AVAILABLE"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    ice_pass = (
        result_df[
            "ICE_Status"
        ]
        == "PASS"
    ).all()

    if "EV_Time_Total_min" in df.columns:

        ev_pass = (
            result_df[
                "EV_Status"
            ]
            == "PASS"
        ).all()

    else:

        ev_pass = True

    print(
        f"ICE time accounting : "
        f"{status(ice_pass)}"
    )

    if "EV_Time_Total_min" in df.columns:

        print(
            f"EV time accounting  : "
            f"{status(ev_pass)}"
        )

    else:

        print(
            "EV time accounting  : "
            "NOT_AVAILABLE"
        )

    overall_pass = (
        ice_pass
        and ev_pass
    )

    result = {

        "Check":
            "Time accounting",

        "ICE_Status":
            status(ice_pass),

        "EV_Status":
            (
                status(ev_pass)
                if
                "EV_Time_Total_min"
                in df.columns
                else
                "NOT_AVAILABLE"
            ),

        "Status":
            (
                "PASS"
                if overall_pass
                else "FAIL"
            ),
    }

    return result, result_df


# ============================================================
# 14. PHASE TIME NON-NEGATIVITY
# ============================================================

def validate_phase_times(df):

    print("\n" + "=" * 70)
    print("8. PHASE TIME VALIDATION")
    print("=" * 70)

    records = []

    all_time_columns = (
        ICE_TIME_COLUMNS
        + EV_TIME_COLUMNS
    )

    for column in all_time_columns:

        values = (
            pd.to_numeric(
                df[column],
                errors="coerce"
            )
        )

        negative_count = int(
            (
                values
                < -1e-9
            )
            .sum()
        )

        records.append({

            "Column":
                column,

            "Negative_Count":
                negative_count,

            "Status":
                (
                    "PASS"
                    if negative_count == 0
                    else
                    "FAIL"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    total_negative = int(
        result_df[
            "Negative_Count"
        ]
        .sum()
    )

    print(
        f"Negative phase-time values : "
        f"{total_negative}"
    )

    result = {

        "Check":
            "Phase time non-negativity",

        "Negative_Values":
            total_negative,

        "Status":
            (
                "PASS"
                if total_negative == 0
                else
                "FAIL"
            ),
    }

    return result, result_df


