# ============================================================
# 16. PHYSICAL CONSISTENCY
# ============================================================
#
# IMPORTANT:
#
# Negative acceleration is physically valid.
#
# Therefore acceleration is deliberately NOT included
# in the non-negative check.
#
# We only require:
#
#     Time >= 0
#     Distance >= 0
#     Speed >= 0
#
# ============================================================

def validate_physical_consistency(df):

    print("\n" + "=" * 70)
    print("10. PHYSICAL CONSISTENCY")
    print("=" * 70)

    records = []

    # --------------------------------------------------------
    # Time
    # --------------------------------------------------------

    time_columns = [
        "ICE_Time_Total_min"
    ]

    if "EV_Time_Total_min" in df.columns:

        time_columns.append(
            "EV_Time_Total_min"
        )

    time_columns += (
        ICE_TIME_COLUMNS
        + EV_TIME_COLUMNS
    )

    # --------------------------------------------------------
    # Distance
    # --------------------------------------------------------

    distance_columns = [
        "ICE_Distance_Total_km"
    ]

    if "EV_Distance_Total_km" in df.columns:

        distance_columns.append(
            "EV_Distance_Total_km"
        )

    distance_columns += (
        ICE_DISTANCE_COLUMNS
        + EV_DISTANCE_COLUMNS
    )

    # --------------------------------------------------------
    # Speed
    # --------------------------------------------------------

    speed_columns = [

        "ICE_Moving_Average_Speed_kmh",

        "EV_Moving_Average_Speed_kmh",
    ]

    # --------------------------------------------------------
    # Check non-negative quantities
    # --------------------------------------------------------

    for column in (
        time_columns
        + distance_columns
        + speed_columns
    ):

        if column not in df.columns:

            continue

        values = pd.to_numeric(
            df[column],
            errors="coerce"
        )

        negative_count = int(
            (
                values
                < -1e-9
            )
            .sum()
        )

        records.append({

            "Column":
                column,

            "Negative_Count":
                negative_count,

            "Status":
                (
                    "PASS"
                    if negative_count == 0
                    else
                    "FAIL"
                ),
        })

    # --------------------------------------------------------
    # Acceleration is NOT required to be positive.
    # --------------------------------------------------------

    acceleration_columns = [

        "ICE_Mean_Acceleration_ms2",

        "EV_Mean_Acceleration_ms2",
    ]

    acceleration_info = []

    for column in acceleration_columns:

        if column not in df.columns:

            continue

        values = pd.to_numeric(
            df[column],
            errors="coerce"
        )

        negative_count = int(
            (
                values
                < 0
            )
            .sum()
        )

        acceleration_info.append({

            "Column":
                column,

            "Negative_Values":
                negative_count,

            "Interpretation":
                (
                    "Allowed; negative acceleration "
                    "represents deceleration."
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    total_violations = int(
        result_df[
            "Negative_Count"
        ]
        .sum()
    )

    print(
        f"Negative values in quantities "
        f"that must be non-negative : "
        f"{total_violations}"
    )

    print(
        "Negative acceleration values "
        "are allowed."
    )

    result = {

        "Check":
            "Physical consistency",

        "Non_Negative_Violations":
            total_violations,

        "Negative_Acceleration":
            "ALLOWED",

        "Status":
            (
                "PASS"
                if total_violations == 0
                else
                "FAIL"
            ),
    }

    acceleration_df = pd.DataFrame(
        acceleration_info
    )

    return (
        result,
        result_df,
        acceleration_df
    )


# ============================================================
# 17. ICE-EV DISTANCE COMPARABILITY
# ============================================================
#
# This is a pair-level comparison.
#
# It checks whether the ICE and EV trips represent
# approximately the same route length.
#
# It does NOT require identical distances.
#
# Current criterion:
#
#     <= 1% difference -> PASS
#
# ============================================================

def validate_distance_comparability(df):

    print("\n" + "=" * 70)
    print("11. ICE-EV DISTANCE COMPARABILITY")
    print("=" * 70)

    # --------------------------------------------------------
    # If EV total distance is stored in the dataset
    # --------------------------------------------------------

    if "EV_Distance_Total_km" in df.columns:

        records = []

        for pair_id, group in (
            df.groupby("Pair_ID")
        ):

            ice_distance = (
                group[
                    "ICE_Distance_Total_km"
                ]
                .sum()
            )

            ev_distance = (
                group[
                    "EV_Distance_Total_km"
                ]
                .sum()
            )

            difference = (
                percentage_difference(
                    ice_distance,
                    ev_distance
                )
            )

            records.append({

                "Pair_ID":
                    pair_id,

                "ICE_Distance_km":
                    ice_distance,

                "EV_Distance_km":
                    ev_distance,

                "Difference_percent":
                    difference,

                "Status":
                    (
                        "PASS"
                        if
                        difference
                        <=
                        DISTANCE_COMPARABILITY_PERCENT
                        else
                        "REVIEW"
                    ),
            })

        result_df = pd.DataFrame(
            records
        )

        pass_count = int(
            (
                result_df[
                    "Status"
                ]
                == "PASS"
            )
            .sum()
        )

        total_pairs = len(
            result_df
        )

        print(
            f"Pairs within "
            f"{DISTANCE_COMPARABILITY_PERCENT}% : "
            f"{pass_count}/{total_pairs}"
        )

        overall_status = (
            "PASS"
            if pass_count
            == total_pairs
            else
            "REVIEW"
        )

        result = {

            "Check":
                "ICE-EV distance comparability",

            "Pairs_Passing":
                pass_count,

            "Total_Pairs":
                total_pairs,

            "Status":
                overall_status,
        }

        return result, result_df

    # --------------------------------------------------------
    # EV total distance not stored
    # --------------------------------------------------------

    print(
        "EV_Distance_Total_km is not stored "
        "in Route_Progress_All."
    )

    print(
        "Distance comparability is therefore "
        "reported as NOT_AVAILABLE here."
    )

    result_df = pd.DataFrame([{

        "Status":
            "NOT_AVAILABLE",

        "Reason":
            (
                "EV total distance is not "
                "stored per route-progress row."
            ),
    }])

    result = {

        "Check":
            "ICE-EV distance comparability",

        "Pairs_Passing":
            np.nan,

        "Total_Pairs":
            np.nan,

        "Status":
            "NOT_AVAILABLE",
    }

    return result, result_df


# ============================================================
# 18. NON-NEGATIVE VARIABLE CHECK
# ============================================================
#
# This replaces the old blanket negative-value scan.
#
# We DO NOT scan every numeric column.
#
# Acceleration can be negative.
# Route-progress-related quantities may also have
# legitimate numerical characteristics.
#
# Only variables that are physically constrained to be
# non-negative are checked.
#
# ============================================================

def validate_non_negative_variables(df):

    print("\n" + "=" * 70)
    print("12. NON-NEGATIVE VARIABLE CHECK")
    print("=" * 70)

    columns_to_check = [

        "ICE_Time_Total_min",
        "ICE_Distance_Total_km",
        "ICE_Moving_Average_Speed_kmh",

        "EV_Moving_Average_Speed_kmh",
    ]

    if "EV_Time_Total_min" in df.columns:

        columns_to_check.append(
            "EV_Time_Total_min"
        )

    if "EV_Distance_Total_km" in df.columns:

        columns_to_check.append(
            "EV_Distance_Total_km"
        )

    columns_to_check += (
        ICE_TIME_COLUMNS
        + EV_TIME_COLUMNS
        + ICE_DISTANCE_COLUMNS
        + EV_DISTANCE_COLUMNS
    )

    records = []

    for column in columns_to_check:

        if column not in df.columns:

            continue

        values = pd.to_numeric(
            df[column],
            errors="coerce"
        )

        negative_count = int(
            (
                values
                < -1e-9
            )
            .sum()
        )

        records.append({

            "Column":
                column,

            "Negative_Count":
                negative_count,

            "Status":
                (
                    "PASS"
                    if negative_count == 0
                    else
                    "FAIL"
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    total_violations = int(
        result_df[
            "Negative_Count"
        ]
        .sum()
    )

    print(
        f"Negative values in physically "
        f"non-negative variables : "
        f"{total_violations}"
    )

    result = {

        "Check":
            "Non-negative variable check",

        "Negative_Values":
            total_violations,

        "Status":
            (
                "PASS"
                if total_violations == 0
                else
                "FAIL"
            ),
    }

    return result, result_df


# ============================================================
# 19. PREDICTIVE PHASE EMPTY-BIN ANALYSIS
# ============================================================
#
# Empty predictive bins are NOT automatically failures.
#
# A route bin can legitimately have no contribution from
# the six predictive phases.
#
# For example, the vehicle may be in an excluded operational
# phase such as:
#
#     Charging
#     Refuelling
#
# Therefore this analysis is INFORMATIONAL.
#
# ============================================================

def analyze_empty_predictive_bins(df):

    print("\n" + "=" * 70)
    print("13. PREDICTIVE PHASE EMPTY-BIN ANALYSIS")
    print("=" * 70)

    records = []

    for pair_id, group in (
        df.groupby("Pair_ID")
    ):

        ice_activity = (
            group[
                ICE_TIME_COLUMNS
            ]
            .sum(axis=1)
            +
            group[
                ICE_DISTANCE_COLUMNS
            ]
            .sum(axis=1)
        )

        ev_activity = (
            group[
                EV_TIME_COLUMNS
            ]
            .sum(axis=1)
            +
            group[
                EV_DISTANCE_COLUMNS
            ]
            .sum(axis=1)
        )

        ice_empty = int(
            (
                ice_activity
                <= 1e-12
            )
            .sum()
        )

        ev_empty = int(
            (
                ev_activity
                <= 1e-12
            )
            .sum()
        )

        records.append({

            "Pair_ID":
                pair_id,

            "ICE_Empty_Bins":
                ice_empty,

            "ICE_Empty_Percent":
                (
                    ice_empty
                    / len(group)
                    * 100
                ),

            "EV_Empty_Bins":
                ev_empty,

            "EV_Empty_Percent":
                (
                    ev_empty
                    / len(group)
                    * 100
                ),

            "Interpretation":
                (
                    "Informational only; "
                    "not automatically a failure."
                ),
        })

    result_df = pd.DataFrame(
        records
    )

    print(
        "\nEmpty predictive bins are "
        "reported for inspection only."
    )

    print(
        "They are NOT used as a mandatory "
        "PASS/FAIL criterion."
    )

    result = {

        "Check":
            "Predictive phase empty bins",

        "Status":
            "INFORMATIONAL",
    }

    return result, result_df


# ============================================================
# 20. DATASET-LEVEL NUMERICAL SANITY
# ============================================================

def validate_numerical_sanity(df):

    print("\n" + "=" * 70)
    print("14. NUMERICAL SANITY")
    print("=" * 70)

    numeric_columns = (
        df.select_dtypes(
            include=np.number
        )
        .columns
    )

    infinite_records = []

    for column in numeric_columns:

        values = pd.to_numeric(
            df[column],
            errors="coerce"
        )

        infinite_count = int(
            np.isinf(
                values.to_numpy()
            )
            .sum()
        )

        infinite_records.append({

            "Column":
                column,

            "Infinite_Count":
                infinite_count,

            "Status":
                (
                    "PASS"
                    if infinite_count == 0
                    else
                    "FAIL"
                ),
        })

    result_df = pd.DataFrame(
        infinite_records
    )

    total_infinite = int(
        result_df[
            "Infinite_Count"
        ]
        .sum()
    )

    print(
        f"Total infinite values : "
        f"{total_infinite}"
    )

    result = {

        "Check":
            "Numerical sanity",

        "Infinite_Values":
            total_infinite,

        "Status":
            (
                "PASS"
                if total_infinite == 0
                else
                "FAIL"
            ),
    }

    return result, result_df


# ============================================================
# 21. OVERALL ASSESSMENT
# ============================================================

def create_overall_assessment(
    structural,
    missing,
    pair_integrity,
    route_bins,
    route_progress,
    distance_accounting,
    time_accounting,
    phase_time,
    phase_distance,
    physical,
    distance_comparability,
    non_negative,
    numerical_sanity,
):

    print("\n" + "=" * 70)
    print("15. OVERALL SCIENTIFIC ASSESSMENT")
    print("=" * 70)

    mandatory_checks = {

        "Structural":
            structural["Status"],

        "Missing values":
            missing["Status"],

        "Pair integrity":
            pair_integrity["Status"],

        "Route-bin completeness":
            route_bins["Status"],

        "Route progress":
            route_progress["Status"],

        "Distance accounting":
            distance_accounting["Status"],

        "Time accounting":
            time_accounting["Status"],

        "Phase time non-negativity":
            phase_time["Status"],

        "Phase distance non-negativity":
            phase_distance["Status"],

        "Physical consistency":
            physical["Status"],

        "Non-negative variables":
            non_negative["Status"],

        "Numerical sanity":
            numerical_sanity["Status"],
    }

    for check_name, check_status in (
        mandatory_checks.items()
    ):

        print(
            f"{check_name:<35}: "
            f"{check_status}"
        )

    all_pass = all(
        value == "PASS"
        for value
        in mandatory_checks.values()
    )

    if all_pass:

        final_status = "PASS"

    else:

        final_status = "REVIEW REQUIRED"

    print(
        "\n"
        + "-" * 70
    )

    print(
        f"FINAL VALIDATION STATUS : "
        f"{final_status}"
    )

    return (
        mandatory_checks,
        final_status
    )


