# ============================================================
# 23. MAIN
# ============================================================

def main():

    # ========================================================
    # LOAD
    # ========================================================

    df = load_dataset()

    # ========================================================
    # VALIDATION 1
    # ========================================================

    structural = (
        validate_structure(df)
    )

    # ========================================================
    # VALIDATION 2
    # ========================================================

    missing = (
        validate_missing_values(df)
    )

    # ========================================================
    # VALIDATION 3
    # ========================================================

    (
        pair_integrity,
        pair_integrity_table
    ) = validate_pair_integrity(df)

    # ========================================================
    # VALIDATION 4
    # ========================================================

    (
        route_bins,
        route_bin_table
    ) = validate_route_bins(df)

    # ========================================================
    # VALIDATION 5
    # ========================================================

    (
        route_progress,
        route_progress_table
    ) = validate_route_progress(df)

    # ========================================================
    # VALIDATION 6
    # ========================================================

    (
        distance_accounting,
        distance_accounting_table
    ) = validate_distance_accounting(df)

    # ========================================================
    # VALIDATION 7
    # ========================================================

    (
        time_accounting,
        time_accounting_table
    ) = validate_time_accounting(df)

    # ========================================================
    # VALIDATION 8
    # ========================================================

    (
        phase_time,
        phase_time_table
    ) = validate_phase_times(df)

    # ========================================================
    # VALIDATION 9
    # ========================================================

    (
        phase_distance,
        phase_distance_table
    ) = validate_phase_distances(df)

    # ========================================================
    # VALIDATION 10
    # ========================================================

    (
        physical,
        physical_table,
        acceleration_table
    ) = validate_physical_consistency(df)

    # ========================================================
    # VALIDATION 11
    # ========================================================

    (
        distance_comparability,
        distance_comparability_table
    ) = validate_distance_comparability(df)

    # ========================================================
    # VALIDATION 12
    # ========================================================

